            continue
        row_unit = None
        if len(row) == len(header) + 1 and roles["weight"] in header:
            wi = header.index(roles["weight"])
            cand = [wi + 1] + list(range(len(row)))
            for ci in cand:
                if ci < len(row) and ci != wi and row[ci].strip().lower() in UNITS:
                    row_unit = row[ci].strip().lower()
