                        break
                month = month_of(str(o.get("shipped_at", "")), "iso")
                status = norm_status(str(o.get("status", "")))
            records.append(dict(num=num, type=rtype, month=month, kg=kg, status=status))
    return seq, records


def read_xml(text):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text.lstrip("﻿"), count=1)
    root = ET.fromstring(text)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = (root.get("weight-unit") or root.get("weight_unit") or "kg").lower()
    records = []
    for el in root.iter("shipment"):
        num = id_number(el.get("id", ""))
        if num is None:
