        num = id_number(rec.get(roles["id"]))
        if num is None:
            continue
        rtype = record_type(rec.get(roles["type"]))
        if depot == "harbor" and rtype == "new" and rec.get(roles["type"], "").strip().upper() not in ("NEW", ""):
            rtype = record_type(rec.get(roles["type"]))
        kg = None
        month = None
        status = None
        if rtype != "void":
            chain = []
