        num = id_number(f["id"])
        if num is None:
            continue
        rtype = record_type(f["type"])
        kg = month = status = None
        if rtype != "void":
            n = Decimal(int(f["weight"]))
            kg = {"g": n * FACTORS["g"], "cskg": n / 100, "dlb": n / 10 * FACTORS["lb"]}[lay["wkind"]]
            try:
                s = f["shipped"]
                if lay["dkind"] == "doy":
                    d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
                else:
                    d = date(int(s[:4]), int(s[4:6]), int(s[6:]))
                month = "%04d-%02d" % (d.year, d.month)
            except ValueError:
                month = None
            status = FW_STATUS.get(f["status"].strip().upper(), "")
        records.append(dict(num=num, type=rtype, month=month, kg=kg, status=status))
    return seq, records


def read_export(depot, raw):
    text = decode(raw)
    if depot == "central":
        return read_xml(text)
    if depot == "north":
        return read_json(text)
    if depot == "south":
        return read_fixed(text)
    return read_delimited(depot, text)


# ---------------------------------------------------------------------- main

def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        if depot not in PRIORITY:
            continue
        with open(path, "rb") as fh:
            seq, recs = read_export(depot, fh.read())
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for _, _, recs in sorted(lst, key=lambda t: (t[0], t[1])):
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    depots = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    handovers = 0
    owners = {}
    for depot in PRIORITY:
        for n in current.get(depot, {}):
            owners.setdefault(n, []).append(depot)
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        r = current[ds[0]][n]
        if r["status"] in COUNTED and r["kg"] is not None:
            depots[ds[0]][0] += 1
            depots[ds[0]][1] += r["kg"]
            if r["month"]:
                m = months.setdefault(r["month"], [0, Decimal(0)])
                m[0] += 1
                m[1] += r["kg"]

    def rnd(x):
        return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

    out = {
        "depots": {d: {"shipments": v[0], "total_kg": rnd(v[1])} for d, v in depots.items()},
        "months": {m: {"shipments": v[0], "total_kg": rnd(v[1])} for m, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as fh:
        json.dump(out, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

